"""Deterministic OCR-content filter benchmark, labels fixed before model inference.

Authored challenge cases plus a supplied, previously collected dialogue corpus.
Ambiguous strings are reported separately and must never be scored as certain signs.
"""
import argparse, json, random
from pathlib import Path

DIALOGUE = '''Go!|No!|Yes.|Stop!|Wait!|Run!|Help!|Duck!|Fire!|Move!|Hide!|Jump!|Quiet!|Sorry.|Thanks.|Okay.|Why?|Who?|Where?|When?|What?|Really?|Again?|Please.|Never.|Enough!|Behind you!|Over here!|Not now.|Come on!|Get down!|Watch out!|Look up!|My turn.|Your call.|I'm here.|He's dead.|She's alive!|We're lost.|It's locked.|John!|Anna?|Michael, wait!|Sarah, get down!|Doctor?|Captain!|Mom!|Dad?|William, listen.|Rose, help me!|My name is Jack.|They call me Black.|Ask Mr. Green.|I saw Rose yesterday.|Meet me in Liberty City.|We need to reach Los Santos.|Follow the blue Ford.|The plate says AB 123 CD.|Write down 6A2 8421.|The code is 1234.|Room 101.|I need 50 dollars.|It's 3:30 already.|Only 2 left!|Three, two, one, go!|B4 is the right door.|Take the M4.|Use the AK-47.|He's driving a BMW.|Press E when I say so.|Don't shoot John.|I never said she stole it.|We can't leave him here.|If you move, they will hear you.|Get the children out first.|I'll cover you. Go!|There's no time for this.|The exit is on your left.|She said, "Run!"|I don't know who you are.|Welcome back, Commander.|He isn't one of them.|This is not a drill.|I owe you one.|Don't trust the sign.|Where did everyone go?|Keep your eyes on the road.|The king is dead.|Long live the queen!|I thought you were gone.|You saved my life.|Don't make me do this.|Nobody gets left behind.|The password is Swordfish.|We're almost there.|That's the last one.|Can you hear me?|I can't see anything.|Tell Anna I am sorry.|The Black Rose is our ship.'''.split('|')
LABELS = '''John Smith|Michael Brown|Sarah Miller|Anna Williams|James Wilson|Emily Davis|Robert Taylor|William Moore|David Anderson|Mary Thomas|Daniel Jackson|Elizabeth White|Joseph Harris|Patricia Martin|Charles Thompson|Jennifer Garcia|Thomas Martinez|Linda Robinson|Christopher Clark|Barbara Lewis|Mark Walker|Susan Hall|Paul Allen|Jessica Young|Steven King|Karen Wright|Andrew Scott|Nancy Green|Joshua Baker|Betty Adams|Kevin Nelson|Margaret Hill|Brian Campbell|Sandra Mitchell|George Roberts|Ashley Carter|Edward Phillips|Kimberly Evans|Ronald Turner|Donna Parker|Liberty City|Los Santos|San Andreas|New Austin|Blackwater|Valentine|Saint Denis|Vice City|Night City|Ravenholm|Whiterun|Solitude|Riften|Windhelm|Riverwood|Red Rocket|Diamond City|Goodneighbor|Novigrad|Oxenfurt|Kaer Morhen|Baldur's Gate|Stormwind|Ironforge|Dunwall|Karnaca|Ford Motor Company|Chevrolet Camaro|Nissan Skyline|Toyota Supra|Volkswagen Golf|Mercedes-Benz|BMW M3|Audi Sport|Porsche 911|Mitsubishi Motors|ACME CORPORATION|NORTHSTAR INDUSTRIES|RAVEN SECURITY|WESTERN SHIPPING|NO PARKING|SPEED LIMIT 50|AUTHORIZED PERSONNEL ONLY|EMPLOYEES ONLY|PRIVATE PROPERTY|OPEN 24 HOURS|FIRE EXIT|EMERGENCY EXIT|ONE WAY|DO NOT ENTER|NO SMOKING|PARKING GARAGE|GAS STATION|POLICE DEPARTMENT|CITY HOSPITAL|CENTRAL BANK|RAILWAY STATION|BUS STOP|ROAD CLOSED|UNDER CONSTRUCTION'''.split('|')
NOISE = '''6A2 8421|1AB 2345|AB 123 CD|ABC-1234|XY 987 ZT|BA 456 CD|5BC 4321|7T8 2094|4P6 7352|2AV 9173|8B0 3659|9AC 5812|3E7 4062|CA-90210|B-MW 432|M-AB 7890|XY12 ZZZ|LM09 ABC|GH20 PQR|AA 123 BB|ZZ 987 YY|XY-12-AB|EF 345 GH|JJ 456 KK|PL 90876|B7G9K2|XQZ7L9|Q4W8E2|ZXCVBNM|qwertyuiop|asdfghjkl|lIlIlIlIlI|0O0O0O0O|IIIIIIIIIIII|1111llll1111|#######|....|||||||||~~~~~~~|!@#$%^&*|xXx__00__xXx|{[]}{}[]|wvvvwwvvv|rnrrnrnrrn|zzzzzzzzzzzz|8B8B8B8B|QZKX VJTP|0x7FFA913C|___---___|000000000000'''.split('|')
AMBIGUOUS = '''Rose|May|Will|Hope|Faith|Grace|Black|White|Green|Brown|King|Queen|Hunter|Chase|River|Summer|June|Mark|Bill|Jack|John|Anna|EXIT|STOP|FIRE|HELP|RUN|GO|OPEN|CLOSED|POLICE|DANGER|YES|NO|OK|404|1234|42|M4|B2'''.split('|')

def main():
    p=argparse.ArgumentParser();p.add_argument('--corpus',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
    old=[json.loads(x) for x in a.corpus.read_text('utf-8').splitlines()][:100]
    rows=[]
    for category,decision,items in [('dialogue_corpus','KEEP',[r['en'] for r in old]),('dialogue_short','KEEP',DIALOGUE),('label','SKIP',LABELS),('noise_plate','SKIP',list(dict.fromkeys(x for x in NOISE if x))) ,('ambiguous','UNCERTAIN',AMBIGUOUS)]:
        ids=list(range(len(items)));random.Random(20261123+len(rows)).shuffle(ids);tuning=set(ids[:round(len(ids)*.4)])
        for i,text in enumerate(items):
            rows.append(dict(id=f'{category}-{i+1:03}',category=category,text=text,expected=decision,split='ambiguous' if decision=='UNCERTAIN' else 'tune' if i in tuning else 'holdout',origin=old[i].get('source_url','prior corpus') if category=='dialogue_corpus' else 'FrameLab authored challenge; synthetic text, no visual context'))
    a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows),'utf-8')
    print(json.dumps({'total':len(rows),'tune':sum(r['split']=='tune' for r in rows),'holdout':sum(r['split']=='holdout' for r in rows),'ambiguous':len(AMBIGUOUS)}))
if __name__=='__main__':main()
